a = input("enter the value of a: ") # This will prompt the user to enter a value and store it in the variable 'a'
b = input("enter the value of b: ") # This will prompt the user to enter a value and store it in the variable 'b'
print ("a is greater than b: ", a > b) # This will compare the values of 'a' and 'b' and print whether 'a' is greater than 'b' or not